CREATE TABLE IF NOT EXISTS legislators (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name VARCHAR(255) NOT NULL, profile_url TEXT, party VARCHAR(100), district VARCHAR(100), status VARCHAR(50) DEFAULT 'active', verified_identity BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS legislative_activities (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, legislator_id UUID NOT NULL REFERENCES legislators(id) ON DELETE CASCADE, kind VARCHAR(100) NOT NULL, title TEXT NOT NULL, description TEXT, date TIMESTAMPTZ NOT NULL, source_url TEXT NOT NULL, verified BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
